class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        vector<vector<int>> res;
        vector<int> cur;
        dfs(0, candidates, target, 0, cur, res);
        return res;
    }
private:
    void dfs(int i, vector<int>& cand, int target, int total, vector<int>& cur, vector<vector<int>>& res) {
        if (total == target) { res.push_back(cur); return; }
        if (i >= (int)cand.size() || total > target) return;
        cur.push_back(cand[i]);
        dfs(i, cand, target, total + cand[i], cur, res);
        cur.pop_back();
        dfs(i + 1, cand, target, total, cur, res);
    }
};

