class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(0, candidates, target, 0, new ArrayList<>(), res);
        return res;
    }
    private void dfs(int i, int[] cand, int target, int total, List<Integer> cur, List<List<Integer>> res) {
        if (total == target) { res.add(new ArrayList<>(cur)); return; }
        if (i >= cand.length || total > target) return;
        cur.add(cand[i]);
        dfs(i, cand, target, total + cand[i], cur, res);
        cur.remove(cur.size() - 1);
        dfs(i + 1, cand, target, total, cur, res);
    }
}

