class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<vector<int>> res;
        vector<int> cur;
        backtrack(0, candidates, target, cur, res);
        return res;
    }
private:
    void backtrack(int start, vector<int>& cand, int remain, vector<int>& cur, vector<vector<int>>& res) {
        if (remain == 0) { res.push_back(cur); return; }
        for (int i = start; i < (int)cand.size(); ++i) {
            if (cand[i] > remain) break;
            cur.push_back(cand[i]);
            backtrack(i, cand, remain - cand[i], cur, res);
            cur.pop_back();
        }
    }
};

